/**
 * glTF asset library. Models live in `src/assets/models/**.glb` (generated by `tools/assets/*.py`,
 * see docs/ASSET_PIPELINE.md). Vite's glob import discovers whichever files exist and gives each a
 * base-path-safe URL, so a missing model simply is not registered and callers can fall back.
 *
 * Conventions: Y-up, metres, front = +Z, origin on the ground at the model's centre.
 */
import type { AnimationClip, BufferGeometry, Material, Mesh, Object3D, Skeleton, SkinnedMesh } from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { MeshoptDecoder } from 'three/addons/libs/meshopt_decoder.module.js';
import { clone } from 'three/addons/utils/SkeletonUtils.js';
import { FULL_GROUP_PREFIXES } from './modelNeeds';

const urls = import.meta.glob('../../assets/models/*.glb', {
  query: '?url',
  import: 'default',
  eager: true,
}) as Record<string, string>;

/**
 * Character models fetched ON DEMAND (docs/CHARACTER_PRODUCTION_ROSTER.md): `models/lazy/*.glb`. Only their URLs are bundled;
 * the boot preload skips them, and the renderer asks for the ones a match needs (`ensure`). A model that fails to load is
 * simply never `has()`, so its caller keeps the existing look.
 */
const lazyUrls = import.meta.glob('../../assets/models/lazy/*.glb', {
  query: '?url',
  import: 'default',
  eager: true,
}) as Record<string, string>;

/** Asset id = file name without extension, e.g. `char_streetBaller`. */
const idOf = (path: string): string =>
  path
    .split('/')
    .pop()!
    .replace(/\.glb$/, '');
const URL_BY_ID = new Map<string, string>(Object.entries(urls).map(([path, url]) => [idOf(path), url]));
const LAZY_URL_BY_ID = new Map<string, string>(
  Object.entries(lazyUrls).map(([path, url]) => [idOf(path), url]),
);

export interface LoadedAsset {
  scene: Object3D;
  clips: AnimationClip[];
}

export class AssetLibrary {
  private readonly assets = new Map<string, LoadedAsset>();
  // the shipped models are meshopt-compressed by the build (scripts/vite/optimizeModels.ts); uncompressed files load as before
  private readonly loader = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
  private failed: string[] = [];

  /** Ids of every eagerly preloaded model file bundled with the build (lazy character models are not included). */
  static availableIds(): string[] {
    return [...URL_BY_ID.keys()];
  }

  /** The URLs of the listed models that are bundled and not loaded yet (what `warmUrls` fetches ahead of a start). */
  static urlsFor(ids: readonly string[], loaded: (id: string) => boolean = () => false): string[] {
    return [...new Set(ids)]
      .filter((id) => !loaded(id))
      .map((id) => LAZY_URL_BY_ID.get(id) ?? URL_BY_ID.get(id))
      .filter((u): u is string => !!u);
  }

  /** Ids of the on-demand character models bundled with the build. */
  static lazyIds(): string[] {
    return [...LAZY_URL_BY_ID.keys()];
  }

  /**
   * Debug / test recorder (docs/MOBILE_PERFORMANCE.md): which model ids the renderer asked for (`touched`; a prefix query
   * is recorded as `prefix*`) and which of those were bundled but NOT loaded at that moment (`missed`: a draw that fell back
   * to its procedural look, or a prefix query that saw fewer models than the build ships). Off (null) outside tests.
   */
  recorder: { touched: Set<string>; missed: Set<string> } | null = null;

  private note(id: string): void {
    const missing = !this.assets.has(id);
    // Safety net (never expected in a verified build): a model somebody asked for that is bundled but not loaded starts
    // loading now, so the NEXT use is right and the procedural fallback is only a one-off. Boot-time and match-start loads
    // make this a no-op in normal play.
    if (missing && this.onDemand && !this.lazyFailed.has(id) && (URL_BY_ID.has(id) || LAZY_URL_BY_ID.has(id)))
      void this.ensureOne(id);
    const r = this.recorder;
    if (!r) return;
    r.touched.add(id);
    if (missing && (URL_BY_ID.has(id) || LAZY_URL_BY_ID.has(id))) r.missed.add(id);
  }

  /** True once the app loads models per start (not all at boot): enables the miss safety net in `note`. */
  onDemand = false;

  private readonly inFlight = new Map<string, Promise<void>>();
  private readonly lazyFailed = new Set<string>();
  /** Fires when an on-demand model finished loading (views re-dress their seats). */
  onLazyLoaded: (() => void) | null = null;

  /**
   * Loads on-demand models (once each); resolves when all settled. Never throws: a failure is remembered and the model is
   * simply never `has()`. Character models announce themselves through `onLazyLoaded` (views re-dress their seats).
   */
  ensure(ids: readonly string[]): Promise<void> {
    return Promise.all(ids.map((id) => this.ensureOne(id).promise)).then(() => undefined);
  }

  private ensureOne(id: string): { promise: Promise<void>; started: boolean } {
    if (this.assets.has(id) || this.lazyFailed.has(id)) return { promise: Promise.resolve(), started: false };
    let job = this.inFlight.get(id);
    if (job) return { promise: job, started: false };
    const url = LAZY_URL_BY_ID.get(id) ?? URL_BY_ID.get(id);
    job = (async () => {
      try {
        if (!url) throw new Error('not bundled');
        const gltf = await this.loader.loadAsync(url);
        this.assets.set(id, { scene: gltf.scene, clips: gltf.animations });
        if (id.startsWith('char_')) this.onLazyLoaded?.();
      } catch (error) {
        console.warn(`[assets] ${id} failed to load`, error);
        this.lazyFailed.add(id);
      } finally {
        this.inFlight.delete(id);
      }
    })();
    this.inFlight.set(id, job);
    return { promise: job, started: true };
  }

  /**
   * Loads the listed models for a start (docs/MOBILE_PERFORMANCE.md): the ones not loaded yet, in parallel, sharing any
   * request already in flight (a prefetch from the Ready screen is not fetched twice). Resolves when all settled, never
   * rejects; null when there is nothing to wait for. `onProgress(done, total)` counts only the models this call waited on.
   */
  load(ids: readonly string[], onProgress?: (done: number, total: number) => void): Promise<void> | null {
    const todo = [...new Set(ids)].filter((id) => !this.assets.has(id) && !this.lazyFailed.has(id));
    if (todo.length === 0) return null;
    let done = 0;
    onProgress?.(0, todo.length);
    return Promise.all(
      todo.map((id) =>
        this.ensureOne(id).promise.then(() => {
          onProgress?.(++done, todo.length);
        }),
      ),
    ).then(() => undefined);
  }

  /** Every bundled model id (eager and on-demand): what an unknown arena loads. */
  static allIds(): string[] {
    return [...new Set([...URL_BY_ID.keys(), ...LAZY_URL_BY_ID.keys()])];
  }

  /**
   * The on-demand loads still in flight (settled together, never rejecting), or null when none: the match loader holds
   * its screen on it for a bounded time so a match's character models are drawn from its first visible frame.
   */
  lazyPending(): Promise<void> | null {
    if (this.inFlight.size === 0) return null;
    return Promise.all([...this.inFlight.values()]).then(() => undefined);
  }

  /** Is the model bundled (so `ensure` can load it) and not known to have failed? */
  canEnsure(id: string): boolean {
    return (LAZY_URL_BY_ID.has(id) || URL_BY_ID.has(id)) && !this.lazyFailed.has(id);
  }

  /** Ids of the models that finished loading (sorted, so derived choices are stable). */
  loadedIds(prefix = ''): string[] {
    const r = this.recorder;
    if (r && prefix) {
      r.touched.add(`${prefix}*`);
      for (const id of [...URL_BY_ID.keys(), ...LAZY_URL_BY_ID.keys()])
        if (id.startsWith(prefix) && !this.assets.has(id) && FULL_GROUP_PREFIXES.includes(prefix))
          r.missed.add(`${prefix}*`);
    }
    return [...this.assets.keys()].filter((i) => i.startsWith(prefix)).sort();
  }

  has(id: string): boolean {
    this.note(id);
    return this.assets.has(id);
  }

  /** Loads the listed models (or all bundled ones) in parallel. Failures are reported, never thrown. */
  async preload(
    ids: string[] = AssetLibrary.availableIds(),
    onProgress?: (done: number, total: number) => void,
  ): Promise<string[]> {
    const failed: string[] = [];
    let done = 0;
    await Promise.all(
      ids.map(async (id) => {
        const url = URL_BY_ID.get(id);
        try {
          if (!url) throw new Error('not bundled');
          const gltf = await this.loader.loadAsync(url);
          this.assets.set(id, { scene: gltf.scene, clips: gltf.animations });
        } catch (error) {
          console.warn(`[assets] ${id} failed to load`, error);
          failed.push(id);
        } finally {
          onProgress?.(++done, ids.length);
        }
      }),
    );
    this.failed = failed;
    return failed;
  }

  failedIds(): string[] {
    return [...this.failed];
  }

  /**
   * A fresh, independently animatable copy (skeletons are re-bound). Returns null if the asset is unavailable.
   *
   * Ownership (docs/CAMPAIGN_CAMERA.md, "Asset lifecycle"): geometries, materials and their textures stay the library's
   * and are shared by every copy; each copy's SKELETON is new and belongs to the caller. The renderer gives a skeleton a
   * bone texture the first time it draws it, and only `Skeleton.dispose()` releases it, so whoever drops a copy calls
   * `releaseSkeletons` on it (the renderer sweeps the whole scene when a match is unloaded).
   */
  instance(id: string): Object3D | null {
    this.note(id);
    const a = this.assets.get(id);
    if (!a) return null;
    const obj = clone(a.scene);
    obj.traverse((o) => {
      const m = o as Mesh;
      if (m.isMesh) {
        m.castShadow = true;
        m.receiveShadow = true;
        m.frustumCulled = false; // skinned bounds are unreliable under animation
      }
    });
    return obj;
  }

  clips(id: string): AnimationClip[] {
    this.note(id);
    return this.assets.get(id)?.clips ?? [];
  }

  /** First mesh of an asset (geometry + material), for building InstancedMeshes from static props. */
  firstMesh(id: string): Mesh | null {
    this.note(id);
    let found: Mesh | null = null;
    this.assets.get(id)?.scene.traverse((o) => {
      const m = o as Mesh;
      if (!found && m.isMesh) found = m;
    });
    return found;
  }

  /**
   * Geometry + material of every mesh in an asset with node transforms baked into the vertices, ready for
   * `InstancedMesh`. Optionally only meshes whose node name matches `filter`.
   */
  parts(
    id: string,
    filter?: (name: string) => boolean,
  ): { name: string; geometry: BufferGeometry; material: Material }[] {
    this.note(id);
    const scene = this.assets.get(id)?.scene;
    if (!scene) return [];
    scene.updateMatrixWorld(true);
    const out: { name: string; geometry: BufferGeometry; material: Material }[] = [];
    scene.traverse((o) => {
      const m = o as Mesh;
      if (!m.isMesh || (filter && !filter(m.name))) return;
      const g = m.geometry.clone();
      g.applyMatrix4(m.matrixWorld);
      out.push({
        name: m.name,
        geometry: g,
        material: Array.isArray(m.material) ? m.material[0]! : m.material,
      });
    });
    return out;
  }

  /** All meshes of an asset with their world matrices applied to a clone of the geometry (see props code). */
  meshes(id: string): Mesh[] {
    this.note(id);
    const out: Mesh[] = [];
    const scene = this.assets.get(id)?.scene;
    scene?.updateMatrixWorld(true);
    scene?.traverse((o) => {
      const m = o as Mesh;
      if (m.isMesh) out.push(m);
    });
    return out;
  }

  dispose(): void {
    for (const a of this.assets.values()) {
      a.scene.traverse((o) => {
        const m = o as Mesh;
        if (!m.isMesh) return;
        m.geometry.dispose();
        for (const mat of Array.isArray(m.material) ? m.material : [m.material]) (mat as Material).dispose();
      });
    }
    this.assets.clear();
  }
}

/**
 * Releases the bone textures of every skeleton under `root` (each skinned copy from `AssetLibrary.instance` has its own;
 * the renderer makes them lazily, so a copy that is drawn again simply gets a new one). Returns how many skeletons it
 * released. Geometry and materials are left alone: they are the library's, shared by every match.
 */
export function releaseSkeletons(root: Object3D): number {
  const seen = new Set<Skeleton>();
  root.traverse((o) => {
    const s = (o as SkinnedMesh).isSkinnedMesh ? (o as SkinnedMesh).skeleton : undefined;
    if (s && !seen.has(s)) {
      seen.add(s);
      s.dispose();
    }
  });
  return seen.size;
}

/** Process-wide library: models are loaded once and shared by every match. */
export const assets = new AssetLibrary();
